// LoadRequestedByUserUser loads the systemUpdateJob's RequestedByUserUser into the .R struct
func (os SystemUpdateJobSlice) LoadRequestedByUserUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	users, err := os.RequestedByUserUser(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.RequestedByUserUser = nil
		o.R.Loaded.RequestedByUserUser = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	systemUpdateJobByKey := make(map[string][]*SystemUpdateJob, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		// NULL never matches any row in SQL, so don't add it to the map
		if !o.RequestedByUserID.IsValue() {
			continue
		}

		systemUpdateJobByKey[o.RequestedByUserID.MustGet()] = append(systemUpdateJobByKey[o.RequestedByUserID.MustGet()], o)
	}

	for _, rel := range users {

		owners, ok := systemUpdateJobByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.RequestedByUserUser != nil {
				continue
			}

			rel.R.RequestedByUserSystemUpdateJobs = append(rel.R.RequestedByUserSystemUpdateJobs, o)

			o.R.RequestedByUserUser = rel

		}
	}

	return nil
}

