func buildSystemUpdateJobCountPreloader() systemUpdateJobCountPreloader {
	return systemUpdateJobCountPreloader{
		JobSystemUpdateJobEvents: func(mods ...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader {
			return countPreloader[*SystemUpdateJob]("JobSystemUpdateJobEvents", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = SystemUpdateJobs.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(sqlite.Raw("count(*)")),

					sm.From(SystemUpdateJobEvents.NameAsExpr()),
					sm.Where(sqlite.Quote(SystemUpdateJobEvents.Alias(), "job_id").EQ(sqlite.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return sqlite.Group(sqlite.Select(subqueryMods...).Expression)
			})
		},
	}
}

