// LoadCountJobSystemUpdateJobEvents loads the count of JobSystemUpdateJobEvents for a slice in a single batch query
func (os SystemUpdateJobSlice) LoadCountJobSystemUpdateJobEvents(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs
	PKArgSlice := make([]bob.Expression, 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		PKArgSlice = append(PKArgSlice, sqlite.Arg(o.ID))
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    string
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			SystemUpdateJobEvents.Columns.JobID.As("id"),
			sqlite.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(SystemUpdateJobEvents.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(SystemUpdateJobEvents.Columns.JobID.OP("IN", PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(SystemUpdateJobEvents.Columns.JobID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		sqlite.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[string]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.JobSystemUpdateJobEvents = &count
	}

	return nil
}

type systemUpdateJobJoins[Q dialect.Joinable] struct {
	typ                      string
	RequestedByUserUser      modAs[Q, userColumns]
	Node                     modAs[Q, nodeColumns]
	JobSystemUpdateJobEvents modAs[Q, systemUpdateJobEventColumns]
}

func (j systemUpdateJobJoins[Q]) aliasedAs(alias string) systemUpdateJobJoins[Q] {
	return buildSystemUpdateJobJoins[Q](buildSystemUpdateJobColumns(alias), j.typ)
}

func buildSystemUpdateJobJoins[Q dialect.Joinable](cols systemUpdateJobColumns, typ string) systemUpdateJobJoins[Q] {
	return systemUpdateJobJoins[Q]{
		typ: typ,
		RequestedByUserUser: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RequestedByUserID),
					))
				}

				return mods
			},
		},
		Node: modAs[Q, nodeColumns]{
			c: Nodes.Columns,
			f: func(to nodeColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Nodes.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.NodeID),
					))
				}

				return mods
			},
		},
		JobSystemUpdateJobEvents: modAs[Q, systemUpdateJobEventColumns]{
			c: SystemUpdateJobEvents.Columns,
			f: func(to systemUpdateJobEventColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, SystemUpdateJobEvents.NameExpr().As(to.Alias())).On(
						to.JobID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
